package com.opensocket.aievent.core.taskauthority.runtime;
import static org.assertj.core.api.Assertions.*;import java.time.*;import java.util.Set;import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import com.opensocket.aievent.core.configuration.runtime.*;import com.opensocket.aievent.core.kernel.configuration.distribution.*;import tools.jackson.databind.json.JsonMapper;
class V41C3R2HTaskAuthorityRuntimeConfigurationViewTest {@Test void snapshotOverridesStartupAndCutoverFailsClosed(){var registry=new RuntimeConfigurationLocalSnapshotRegistry();var values=new RuntimeConfigurationSnapshotValues(registry,JsonMapper.builder().build());var authority=new RuntimeConfigurationAuthorityRegistry();var startup=new MockEnvironment().withProperty(TaskAuthorityRuntimeConfigurationView.FINALIZATION_BATCH_SIZE,"7");var view=new TaskAuthorityRuntimeConfigurationView(values,authority,startup);assertThat(view.finalizationBatchSize()).isEqualTo(7);registry.atomicSwap(snapshot(payload()));assertThat(view.finalizationBatchSize()).isEqualTo(25);assertThat(view.projectionMaxAttempts()).isEqualTo(30);authority.activate(Set.of(TaskAuthorityRuntimeConfigurationView.FINALIZATION_BATCH_SIZE));registry.atomicSwap(snapshot("{}"));assertThatThrownBy(view::finalizationBatchSize).isInstanceOf(IllegalStateException.class);}private static String payload(){return "{\"opendispatch.a0-r2.conditions.enabled\":true,\"opendispatch.a0-r2.conditions.batch-size\":120,\"opendispatch.a0-r2.conditions.poll-ms\":6000,\"opendispatch.a0-r2.finalization.enabled\":true,\"opendispatch.a0-r2.finalization.batch-size\":25,\"opendispatch.a0-r2.finalization.claim-seconds\":70,\"opendispatch.a0-r2.finalization.max-attempts\":9,\"opendispatch.a0-r2.finalization.poll-ms\":2500,\"opendispatch.a0-r2.finalization.projection-enabled\":true,\"opendispatch.a0-r2.finalization.projection-batch-size\":60,\"opendispatch.a0-r2.finalization.projection-claim-seconds\":75,\"opendispatch.a0-r2.finalization.projection-max-attempts\":30,\"opendispatch.a0-r2.finalization.projection-poll-ms\":3500}";}private static RuntimeConfigurationSnapshotEnvelope snapshot(String payload){var now=OffsetDateTime.of(2026,9,24,2,0,0,0,ZoneOffset.UTC);return new RuntimeConfigurationSnapshotEnvelope("LOCAL","task-authority",TaskAuthorityRuntimeConfigurationView.SET_KEY,"r1",1,7,now,now.plusHours(1),"CORE",payload,"hash","sig");}}
